def word_frequency(text: str) -> dict[str, int]:
    import string
    freq = {}
    if not text:
        return freq
    for w in text.split():
        w = w.strip(string.punctuation)
        if not w:
            continue
        w = w.lower()
        freq[w] = freq.get(w, 0) + 1
    return freq
